defmodule LedgerUI.ThemeGeneratorTest do
  # assets/css/ledger_ui.css is GENERATED by scripts/tw/tw_theme.py (tokens.json + the @keyframes of the reference's bundle.css).
  # This test regenerates it into a temp file and fails if the versioned CSS drifted (a hand edit, or a generator change
  # without regenerating). It needs python3 and the reference repo (../ledger_ui_ref, or LEDGER_REF), which is not part of
  # the Hex package: without them it is skipped.
  use ExUnit.Case, async: true

  @root Path.expand("../..", __DIR__)
  @ref_candidates [
    System.get_env("LEDGER_REF"),
    Path.join(@root, "../ledger_ui_ref"),
    Path.join(@root, "../../ledger_ui_ref")
  ]
  @has_ref Enum.any?(
             @ref_candidates,
             &(&1 && File.exists?(Path.join(&1, "referencia/tokens.json")))
           )
  @skip (cond do
           System.find_executable("python3") == nil -> "python3 not found"
           not @has_ref -> "reference repo (ledger_ui_ref / LEDGER_REF) not found"
           true -> false
         end)

  @tag skip: @skip
  test "the versioned CSS equals what scripts/tw/tw_theme.py generates" do
    out = Path.join(System.tmp_dir!(), "ledger_ui_gen_#{System.unique_integer([:positive])}.css")
    on_exit(fn -> File.rm(out) end)

    {log, status} =
      System.cmd("python3", [Path.join(@root, "scripts/tw/tw_theme.py")],
        env: [{"LEDGER_UI_CSS_OUT", out}],
        stderr_to_stdout: true
      )

    assert status == 0, log

    assert File.read!(out) == File.read!(Path.join(@root, "assets/css/ledger_ui.css")),
           "assets/css/ledger_ui.css drifted from the generator: edit scripts/tw/ (tokens.json / tw_theme.py) and run python3 scripts/tw/tw_theme.py"
  end
end
